// Usage: node benchmarks/eval/s1-4-defaults.mjs [--limit 150] [--json] [DATASET ...]; needs target/release/layout-command
// and `npm ci` in benchmarks/eval (elk-rs).
// ADR 0020, step S1-4: the candidates for the default against the default and elk-rs on the datasets in
// benchmarks/datasets (generated by benchmarks/generate.py; the very large ones left out). Each variant is one import of
// the dataset's bounded view (`limit` nodes) with the variant's options; elk-rs layered gets the view the default selected
// (the same nodes and edges, in the view's default direction: elk-rs takes no per-container directions across a hierarchy,
// as in compare.mjs). One metric
// implementation scores every drawing (node shapes included). Single runs: the times are indicative only.
import {readdirSync, existsSync, readFileSync} from 'node:fs';
import {arqlet, normalizeArqlet, metrics, ROOT} from './lib.mjs';
import {elkLayout} from './elk-adapter.mjs';
import ElkRs from '@openedges/elk-layout';

const args = process.argv.slice(2);
const option = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 ? args.splice(i, 2)[1] : fallback;
};
const LIMIT = Number(option('--limit', 150));
const JSON_OUT = args.includes('--json') && (args.splice(args.indexOf('--json'), 1), true);
const SKIP = /^(synthetic-20k|protocol-|overview-|intentweave|organic-300)/;
const selected = args.length ? args : readdirSync(`${ROOT}benchmarks/datasets`)
  .filter(f => f.endsWith('.json') && !SKIP.test(f)).map(f => f.slice(0, -5)).sort();

const A = {singlePassMixed: true, regionPorts: true, straightDetours: true, singlePassReversed: true};
export const VARIANTS = {
  'default': {},
  'A': A,
  'A + regionChildPorts': {...A, regionChildPorts: true},
  'B': {regionPorts: true, straightDetours: true, singlePassReversed: true},
  'directionsFirst': {directionsFirst: true},
};

const rows = [];
for (const name of selected) {
  const file = `${ROOT}benchmarks/datasets/${name}.json`;
  if (!existsSync(file)) continue;
  const raw = JSON.parse(readFileSync(file, 'utf8'));
  const graph = raw.graph ?? raw;
  let view = null;
  for (const [variant, options] of Object.entries(VARIANTS)) {
    let snapshot, ms;
    try {
      ({snapshot, ms} = arqlet({op: 'import', graph, limit: LIMIT, options}));
    } catch (error) {
      rows.push({dataset: name, variant, error: String(error.message ?? error).slice(0, 200)});
      continue;
    }
    view ??= snapshot.graph;
    const m = metrics(normalizeArqlet(snapshot));
    rows.push({dataset: name, variant, nodes: snapshot.graph.nodes.length, edges: snapshot.graph.edges.length,
      lineNodeHits: m.lineNodeHits, crossings: m.crossings, bends: m.bends, areaK: Math.round(m.area / 1e3),
      geometryIssues: (snapshot.geometryIssues ?? []).length,
      singlePass: (snapshot.layoutDiagnostics ?? []).some(d => d.startsWith('Single pass:')), ms: Math.round(ms)});
  }
  if (view) {
    try {
      const elk = await elkLayout(view, new ElkRs());
      const m = metrics(elk);
      rows.push({dataset: name, variant: 'elk-rs', nodes: view.nodes.length, edges: view.edges.length, lineNodeHits: m.lineNodeHits,
        crossings: m.crossings, bends: m.bends, areaK: Math.round(m.area / 1e3), geometryIssues: null, singlePass: null, ms: Math.round(elk.ms)});
    } catch (error) {
      rows.push({dataset: name, variant: 'elk-rs', error: String(error.message ?? error).slice(0, 200)});
    }
  }
}
if (JSON_OUT) for (const r of rows) console.log(JSON.stringify(r));
else {
  console.log('| dataset | variant | nodes/edges | line–node hits | crossings | bends | area (k) | geometry issues | single pass | ms |');
  console.log('|---|---|---|---|---|---|---|---|---|---|');
  for (const r of rows) console.log(r.error ? `| ${r.dataset} | ${r.variant} | error: ${r.error} |||||||| `
    : `| ${r.dataset} | ${r.variant} | ${r.nodes}/${r.edges} | ${r.lineNodeHits} | ${r.crossings} | ${r.bends} | ${r.areaK} | ${r.geometryIssues ?? '–'} | ${r.singlePass === null ? '–' : r.singlePass ? 'yes' : 'no'} | ${r.ms} |`);
}
